/* Minimal BSD <sys/types.h> for porting usenet sources to OS-9/68k. * * The typedefs live in SRC/COMPAT/types.h now, guarded, because some ports ask * for <types.h> and some for <sys/types.h> and a file that reaches both must * not get each typedef twice. * * NOTE: dev_t is deliberately NOT defined -- DEFS/UNIX/stat.h declares it as * char* (a device NAME), and redefining it as a scalar breaks stat.h. */#include <types.h>